function openArchive(){$('archivelist').innerHTML=buildingState.data.archive.map(a=>`<div class="archive-row"><b>${esc(a.name)}</b><div>${!a.savedOnly?`<button data-archive="${esc(a.id)}" data-saved="false">Open original as building</button>`:''}${a.saved?`<button data-archive="${esc(a.id)}" data-saved="true">${a.savedOnly?'Restore archived building':'Open saved edits as building'}</button>`:''}</div></div>`).join('');$('archivedialog').showModal()}
function fileName(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'building'}
function exportBuilding(){if(buildingState.locked||$('saved').dataset.state==='error'){exportRecovery();return}finishWidthEdit(false);finishDrag(true);captureBuilding();const building=clone(currentBuilding());window.KERN_OBJECTS?.normalizeAnnotations(building.plan);download(fileName(building.name)+'-building.json',JSON.stringify({format:'kern-building',schemaVersion:1,building},null,2),'application/json');notify('Building exported · all its floors and edits')}
function exportRecovery(){const snapshot={...buildingState,data:clone(buildingState.data)},b=snapshot.data.buildings.find(b=>b.id===snapshot.data.activeBuildingId);if(b)b.plan=clone(model);const backup=window.KERN_BUILDINGS.recoveryBackup(localStorage,snapshot);download('planner-recovery-backup.json',JSON.stringify(backup,null,2),'application/json');notify(Object.keys(backup.readErrors).length?'Partial recovery backup downloaded · some browser records could not be read':'Recovery backup downloaded · exact saved records and visible workspace preserved')}
