function importBuildings(p,name){if(p?.format==='kern-storage-recovery')p=window.KERN_BUILDINGS.readRecovery(p,validateImport);let items;if(p?.format==='kern-building'&&p.schemaVersion===1)items=[p.building];else if(p?.format==='kern-buildings'){window.KERN_BUILDINGS.validate(p,validateImport);items=p.buildings}else{validateImport(p);items=[{name:p.title||name,plan:p,sourceVariant:p.variant||'custom'}]}if(!items.length||items.length+buildingState.data.buildings.length>100)throw Error('Limit: 100 buildings');const copies=items.map(b=>{validateImport(b.plan);const n=window.KERN_BUILDINGS.building(b.name||name,b.plan,b.sourceVariant||'custom');n.view=clone(b.view||window.KERN_BUILDINGS.view());return n});const importedArchive=p.format==='kern-buildings'?(p.archive||[]):[];const extraArchive=importedArchive.filter(a=>a.saved&&!buildingState.data.archive.some(x=>!a.buildingSnapshot&&!x.buildingSnapshot&&x.sourceVariant===a.sourceVariant&&x.saved===a.saved));if(buildingState.data.archive.length+extraArchive.length>200)throw Error('This backup has too many archived saves to add safely');finishWidthEdit(false);resetTransient(true);save();buildingState.data.buildings.push(...copies);for(const a of importedArchive){if(a.saved&&!buildingState.data.archive.some(x=>!a.buildingSnapshot&&!x.buildingSnapshot&&x.sourceVariant===a.sourceVariant&&x.saved===a.saved))buildingState.data.archive.push({...clone(a),id:'import-'+window.KERN_BUILDINGS.id(),name:(a.name+' · imported backup').slice(0,180)})}buildingState.data.activeBuildingId=copies[0].id;loadBuilding(copies[0]);render();save();notify(copies.length+' building'+(copies.length===1?'':'s')+' imported as separate copies')}
function nameSafeFloorId(id){return /^[A-Za-z0-9_-]{1,20}$/.test(id)&&!['__proto__','constructor','prototype'].includes(id)}
