function removeFloor(approved=false){if(floorId==='L0')return;const id=floorId;if(approved!==true&&!confirm('Remove '+id+' and all its rooms and connections? Linked references to this floor will also be removed. Undo restores the complete building.'))return;commit(()=>{delete model.floors[id];if(model.walkStart?.floor===id)delete model.walkStart;for(const f of Object.values(model.floors))for(const r of f.rooms)if(r.linkedSource?.floor===id){delete r.linkedSource;r.locked=false}if(model.verticalConnections)model.verticalConnections=model.verticalConnections.map(c=>{c.floors=(c.floors||[]).filter(f=>f!==id);if(c.footprints)delete c.footprints[id];return c}).filter(c=>c.floors.length>=2);if(model.splitLevelConnections)model.splitLevelConnections=model.splitLevelConnections.filter(c=>c.floor!==id&&c.from!==id&&c.to!==id);if(model.courtyard?.floor===id)delete model.courtyard;floorId='L0';selected=null;selectedDoor=null;viewBounds=null});closeToolbarMenus()}



function isStair(r,fid=floorId){return !!r&&(r.stairTransition||/stair/i.test(r.id)||[...(model.verticalConnections||[]),...(model.splitLevelConnections||[])].some(c=>c.room===r.id&&c.type!=='lift'&&(c.floor===fid||c.floors?.includes(fid))))}
