  $('stairpreviewtitle').textContent=d.name+' · height slices';$('stairheight').innerHTML=state.levels.map((l,i)=>`<option value="${i}" ${i===state.index?'selected':''}>${esc(l.label||((l.z>=0?'+':'')+l.z.toFixed(2)+' m'))}</option>`).join('');
