document.addEventListener?.('focusin',e=>{if(!e.target.closest?.('.toolbar-popover'))closeToolbarMenus();if(connectionMenu&&!e.target.closest?.('#connectionmenu'))closeConnectionMenu();if(isTypingTarget(e.target)&&(spaceHeld||drag))resetTransient(true,true)});
