window.kernPlanner={getPlan:()=>clone(model),getGeometry:()=>buildGeometry(model),checks,doorGeometry,validateImport};if(document.modelContext?.registerTool){for(const tool of [{name:'read_kern_plan',description:'Read the current plan and validation findings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({plan:clone(model),checks:Object.fromEntries(Object.entries(model.floors).map(([id,f])=>[id,checks(f)]))})},{name:'select_kern_floor',description:'Show one floor in the planner.',inputSchema:{type:'object',properties:{floor:{type:'string'}},required:['floor'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Object.hasOwn(model.floors,input.floor))throw Error('Unknown floor');if(window.KERN_LAYERS)window.KERN_LAYERS.activateFloor(input.floor);else{floorId=input.floor;selected=null;render();}return{floor:floorId}}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(console.warn)}catch(e){console.warn(e)}}buildingState=window.KERN_BUILDINGS.load(localStorage,seedFor,validateImport);loadBuilding(currentBuilding());render();if(buildingState.locked){$('saved').textContent='Not saved · download a backup';$('saved').dataset.state='error'}else{$('saved').textContent='Saved locally · this browser';$('saved').dataset.state='saved'}if(buildingState.message)notify(buildingState.message);window.addEventListener?.('pagehide',saveView);

const toolbarMenuIds=['filemenu','viewmenu','buildingmenu','symbolmenu','servicemenu','placemenu'];
function closeToolbarMenus(restoreFocus=false){for(const id of toolbarMenuIds){const details=$(id);if(details?.open){details.open=false;if(restoreFocus)details.querySelector?.('summary')?.focus({preventScroll:true})}}}
function wireToolbarMenu(id){const details=$(id);if(!details)return;details.ontoggle=()=>{if(details.open)for(const other of toolbarMenuIds)if(other!==id&&$(other))$(other).open=false};}
for(const id of toolbarMenuIds)wireToolbarMenu(id);

function canConvertStair(r){return !!r&&!(model.splitLevelConnections||[]).some(c=>c.room===r.id&&c.floor===floorId)&&canEdit(r)&&!isSourceRoom(r)&&!['void','solid','courtyard'].includes(r.type)&&!(model.verticalConnections||[]).some(c=>c.room===r.id)}
function changeFloorElevation(elevation){const value=typeof elevation==='number'?elevation:prompt('Elevation for '+floorId+' in metres. Stairs recalculate; custom room elevations stay unchanged:',String(floor().z));if(value===null)return;const z=Number(value);if(!Number.isFinite(z)||Math.abs(z)>150){alert('Use an elevation within ±150 m.');return}commit(()=>{floor().z=z;floor().elevation=(z>0?'+':'')+z.toFixed(2)+' m'});closeToolbarMenus()}
function editFloorProperties(){closeToolbarMenus();$('buildingmenu').open=true;$('renamefloor').focus?.()}
function stairCreationScopeValid(){return !!stairCreateState&&stairCreateState.floorId===floorId&&stairCreateState.buildingId===currentBuilding()?.id}
function closeStairCreation(){stairCreateState=null;$('staircreate').close();refreshInteraction()}
function openStairCreation(roomId=null,footprint=null){
 if(!roomId&&!footprint){resetTransient(true);setTool('stairs');closeToolbarMenus();return}
 if(roomId)resetTransient(true);closeToolbarMenus();const r=roomId?room(roomId):null,c=r?window.KERN_STAIR_AUTHOR.linked(model,floorId,r.id):null;
 if(roomId&&!r)return;
 if(r&&!c&&!canConvertStair(r)){notify('This is a protected or local split-level stair. Draw a separate stair stack.');return}
 const shape=r||footprint;
 stairCreateState={roomId:r?.id||null,stackId:c?.id||null,floorId,buildingId:currentBuilding()?.id,floors:c?[...c.floors]:[floorId],proposal:null,fit:false,drawn:!r};
 $('staircreatetitle').textContent=c?'Edit connected floors':r?'Convert to stairs':'Connect your stairs';$('stairintro').textContent=c?'Choose destination floors for this stack. Its footprints stay aligned.':r?'Keep this room’s footprint and doors. Choose a destination, then review the stair fit.':'Footprint drawn on '+floorId+'. Choose where it goes, then review the stair fit.';
 $('stairorigin').textContent=floorId+' · '+floor().name+' · '+Number(floor().z).toFixed(2)+' m';$('redrawstair').hidden=!!r;
 for(const [key,value]of Object.entries({name:r?.name||'Stairs',x:shape.x,y:shape.y,w:shape.w,h:shape.h,axis:r?.runAxis||(shape.h>shape.w?'y':'x')}))$('stair'+key).value=value;
 $ ('stairtype').value=r?.stairType||c?.stairType||'switchback';$('spiralhand').value=r?.spiralHand||c?.spiralHand||'right';updateStairEnds(r?.landingEnd||c?.landingEnd);renderStairFloorChoices();renderStairCreation();$('staircreate').showModal();$('stairfloors').querySelector?.('input:not(:disabled)')?.focus?.();
}
function renderStairFloorChoices(){const st=stairCreateState;if(!st)return;$('stairfloors').innerHTML=Object.entries(model.floors).filter(([id])=>id!==st.floorId).sort((a,b)=>b[1].z-a[1].z).map(([id,f])=>`<label><input type="checkbox" data-stair-floor="${esc(id)}" ${st.floors.includes(id)?'checked':''}><span><b>${esc(id)}</b> ${esc(f.name)}</span><small>${f.z>0?'+':''}${Number(f.z).toFixed(2)} m</small></label>`).join('')||'<p class="small">Add another floor using Manage, then draw the stairs again.</p>'}

function updateStairEnds(value){const axis=$('stairaxis').value,ends=axis==='x'?['west','east']:['north','south'];$('stairend').innerHTML=ends.map(e=>`<option value="${e}">${e[0].toUpperCase()+e.slice(1)}</option>`).join('');$('stairend').value=ends.includes(value)?value:ends[0]}
function stairCreationInput(){return {floorId:stairCreateState.floorId,roomId:stairCreateState.roomId,floors:stairCreateState.floors,name:$('stairname').value,x:Number($('stairx').value),y:Number($('stairy').value),w:Number($('stairw').value),h:Number($('stairh').value),runAxis:$('stairaxis').value,landingEnd:$('stairend').value,stairType:$('stairtype').value,spiralHand:$('spiralhand').value}}
function renderStairCreation(){
 const st=stairCreateState;if(!st)return;$('spiralhandfield').hidden=$('stairtype').value!=='spiral';if(!stairCreationScopeValid()){closeStairCreation();return}const button=$('savestair');st.proposal=null;st.fit=false;button.disabled=true;button.textContent=st.stackId?'Save connected floors':st.roomId?'Convert to stairs':'Create stairs';try{
  if(st.floors.length<2)throw Error('Choose at least one destination floor. The starting floor is '+st.floorId+'.');
  const proposal=window.KERN_STAIR_AUTHOR.prepare(model,stairCreationInput()),d=window.KERN_STAIR_DETAIL.build(proposal.plan,floorId,proposal.roomId),r=d.footprint,details=proposal.floors.map(f=>window.KERN_STAIR_DETAIL.build(proposal.plan,f,proposal.roomId));st.proposal=proposal;
  const warnings=[...proposal.notices,...details.flatMap(d=>d.warnings.map(w=>d.floorId+': '+w.text))],issues=[...new Set(warnings)],fit=details.every(d=>d.fit),m=d.metrics;const fatal=details.some(d=>d.warnings.some(w=>w.severity==='error'&&!['no-door','door-landing','shaft-blocked'].includes(w.code)));st.fit=fit&&!fatal;button.disabled=!st.fit;
  $('stair-create-plan').setAttribute('viewBox',`${r.x-1} ${r.y-1} ${r.w+2} ${r.h+2}`);$('stair-create-plan').innerHTML=themedMarkup(`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="#d9ddda" stroke="#34464b" stroke-width=".12"/>`+window.KERN_STAIR_DETAIL.markup(d));
  $('staircreatechecks').innerHTML=`<p class="stair-status ${!fit||issues.length?'warning':''}">${!fit?'Footprint too small or misaligned':issues.length?'Footprint fits · access / openings to review':'Fits · clearance conditional'}</p><p class="small">${!fit?'Make the footprint larger in the fields'+(st.drawn?' or choose Redraw footprint':'')+'. ':''}Minimum envelope ${m.requiredEnvelope.long.toFixed(2)} × ${m.requiredEnvelope.short.toFixed(2)} m · ${m.clearWidth.toFixed(1)} m clear width · ${(m.riserMax*1000).toFixed(0)} mm risers</p>${d.segments.map(s=>`<p class="small"><b>${esc(s.from)} ↔ ${esc(s.to)}</b> · ${s.rise.toFixed(2)} m rise · ${s.risers} risers · ${s.flights.length} flights</p>`).join('')}${issues.map(w=>`<p class="check warn">△ ${esc(w)}</p>`).join('')}<p class="small">${d.openings.length} required slab / services / ceiling opening(s). Add access doors at the ${esc(d.landingEnd)} arrival end; no doors are invented.</p>`;
  button.textContent=st.stackId?'Save connected floors':st.roomId?'Convert to stairs':'Create stairs';
 }catch(error){st.proposal=null;button.disabled=true;const r=stairCreationInput();$('stair-create-plan').setAttribute('viewBox',`${r.x-1} ${r.y-1} ${r.w+2} ${r.h+2}`);$('stair-create-plan').innerHTML=Number.isFinite(r.w)&&r.w>0&&Number.isFinite(r.h)&&r.h>0?themedMarkup(`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="#d9ddda" stroke="#34464b" stroke-width=".12"/>`):'';$('staircreatechecks').innerHTML=`<p class="check warn">${esc(error.message)}</p>`}
}
function saveStairCreation(){if(!stairCreateState)return;renderStairCreation();const state=stairCreateState,proposal=state?.proposal;if(!proposal||!state.fit)return;closeStairCreation();commit(()=>{model=proposal.plan;setSelection({rooms:[proposal.roomId],doors:[]})});finishOneShot(true);notify('Stairs saved across '+proposal.floors.join(', ')+' · review access doors in the inspector');$('plan').focus?.()}

function deleteStairStack(c){const count=c.floors.reduce((n,id)=>n+(model.floors[id]?.doors.filter(d=>d.a===c.room||d.b===c.room).length||0),0);if(!confirm('Delete this stair stack on '+c.floors.join(', ')+' and '+count+' access connections? Undo restores the complete stack.'))return;commit(()=>{model=window.KERN_STAIR_AUTHOR.remove(model,c.id);selected=null;selectedDoor=null});notify('Stair stack deleted · Undo restores all connected floors')}
$('createstairs').onclick=()=>tool==='stairs'?setTool('select'):openStairCreation();$('cancelstair').onclick=closeStairCreation;$('redrawstair').onclick=()=>{closeStairCreation();setTool('stairs');notify('Draw a new stair footprint on '+floorId)};$('staircreate').onclose=()=>{stairCreateState=null;refreshInteraction()};$('staircreate').oncancel=e=>{e.preventDefault();closeStairCreation()};$('savestair').onclick=saveStairCreation;
$('stairfloors').onchange=e=>{const id=e.target.dataset.stairFloor;if(!id||!stairCreateState||id===stairCreateState.floorId)return;stairCreateState.floors=e.target.checked?[...new Set([...stairCreateState.floors,id])]:stairCreateState.floors.filter(f=>f!==id);renderStairCreation()};
for(const key of ['name','x','y','w','h','end'])$('stair'+key).oninput=renderStairCreation;$('stairaxis').onchange=()=>{updateStairEnds();renderStairCreation()};
$('quickaddfloor').onclick=addFloor;$('floorz').onclick=changeFloorElevation;$('editfloorproperties').onclick=editFloorProperties;$('newconnectiontype').onchange=e=>setNewConnectionKind(e.target.value);$('theme').onchange=e=>setTheme(e.target.value);$('snapsize').onchange=e=>setSnapSize(e.target.value);$('newconnectiontype').value=connectionKind;applyTheme();

